const body = $json.body && typeof $json.body === 'object' ? $json.body : {};
const headers = $json.headers || {};
return {
  json: {
    topic: body.topic,
    style: body.style,
    audience: body.audience,
    tone: body.tone,
    word_target: body.word_target,
    image_aspect: body.image_aspect,
    simulate: body.simulate,
    include_image_base64: body.include_image_base64 === true,
    source: 'api',
    request_id: headers['x-request-id'] || null,
    received_at: Date.now()
  }
};

const raw = $input.first().json.error;
const message = typeof raw === 'string' ? raw : String((raw && raw.message) || 'Unknown error');
const timedOut = /timed? ?out|timeout|cancel/i.test(message);
return [{
  json: {
    status_code: timedOut ? 504 : 500,
    body: {
      status: 'error',
      error: timedOut ? 'The run did not finish within the time limit' : 'Unexpected workflow error',
      detail: message.slice(0, 300),
      execution_id: $execution.id
    }
  }
}];

const item = $input.first();
const result = item.json;
const body = Object.assign({}, result);
delete body.http_status;
const wantsImage = $('Normalize API Request').first().json.include_image_base64;
if (wantsImage && item.binary && item.binary.image) {
  const buffer = await this.helpers.getBinaryDataBuffer(0, 'image');
  body.image = Object.assign({}, body.image, { mime_type: item.binary.image.mimeType, base64: buffer.toString('base64') });
}
return [{ json: { status_code: result.http_status || 200, body } }];

const f = $json;
const pick = (...keys) => {
  for (const key of keys) {
    if (f[key] !== undefined && f[key] !== null) return f[key];
  }
  return '';
};
return {
  json: {
    topic: pick('topic', 'Topic'),
    style: pick('style', 'Style'),
    audience: pick('audience', 'Audience (optional)'),
    tone: pick('tone', 'Tone (optional)'),
    image_aspect: pick('image_aspect', 'Image shape'),
    source: 'form',
    received_at: Date.now()
  }
};

const raw = $input.first().json.error;
const message = typeof raw === 'string' ? raw : String((raw && raw.message) || 'Unknown error');
const esc = value => String(value).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const html = '<!doctype html><html><head><meta charset="utf-8"><title>Generation failed</title></head>'
  + '<body style="font:16px/1.6 -apple-system,sans-serif;max-width:640px;margin:48px auto;padding:0 16px">'
  + '<h1>Something went wrong</h1><p>The workflow stopped unexpectedly. It has been logged for review.</p>'
  + '<p><code>' + esc(message.slice(0, 300)) + '</code></p><p>Execution ' + esc($execution.id) + '</p>'
  + '<p><a href="/form/content-form">Try again</a></p></body></html>';
return [{ json: { html } }];

const item = $input.first();
const r = item.json;
const esc = value => String(value === undefined || value === null ? '' : value)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const inline = text => esc(text)
  .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
  .replace(/\*([^*\s][^*]*?)\*/g, '<em>$1</em>');

// Minimal Markdown renderer for the pipeline's own output (headings, paragraphs, lists, quotes).
const toHtml = markdown => {
  const out = [];
  let list = null;
  let para = [];
  const flush = () => {
    if (para.length) out.push('<p>' + inline(para.join(' ')) + '</p>');
    para = [];
  };
  const closeList = () => {
    if (list) out.push('</' + list + '>');
    list = null;
  };
  for (const raw of String(markdown || '').split('\n')) {
    const line = raw.trim();
    let m;
    if (!line) { flush(); closeList(); continue; }
    if ((m = /^(#{1,6})\s+(.*)$/.exec(line))) { flush(); closeList(); out.push('<h' + m[1].length + '>' + inline(m[2]) + '</h' + m[1].length + '>'); continue; }
    if ((m = /^[-*+]\s+(.*)$/.exec(line))) { flush(); if (list !== 'ul') { closeList(); out.push('<ul>'); list = 'ul'; } out.push('<li>' + inline(m[1]) + '</li>'); continue; }
    if ((m = /^\d+[.)]\s+(.*)$/.exec(line))) { flush(); if (list !== 'ol') { closeList(); out.push('<ol>'); list = 'ol'; } out.push('<li>' + inline(m[1]) + '</li>'); continue; }
    if ((m = /^>\s?(.*)$/.exec(line))) { flush(); closeList(); out.push('<blockquote>' + inline(m[1]) + '</blockquote>'); continue; }
    closeList();
    para.push(line);
  }
  flush();
  closeList();
  return out.join('\n');
};

const css = 'body{margin:0;background:#f4f5f7;font:16px/1.65 -apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif;color:#1d2330}'
  + '.wrap{max-width:820px;margin:32px auto;background:#fff;border-radius:14px;box-shadow:0 2px 18px rgba(0,0,0,.08);overflow:hidden}'
  + '.meta{padding:18px 28px;background:#111827;color:#e5e7eb;font-size:13px;display:flex;flex-wrap:wrap;gap:8px 16px}'
  + '.badge{padding:2px 10px;border-radius:999px;font-weight:600;text-transform:uppercase;letter-spacing:.04em}'
  + '.ok{background:#16a34a;color:#fff}.warn{background:#d97706;color:#fff}.bad{background:#dc2626;color:#fff}'
  + '.content{padding:8px 28px 28px}.content h1{font-size:30px;line-height:1.25;margin:20px 0 8px}.lede{color:#4b5563;margin:0 0 16px}'
  + '.content img{width:100%;border-radius:10px;margin:8px 0 16px}.content h2{margin:28px 0 10px}.content h3{margin:20px 0 8px}'
  + '.content p{margin:0 0 14px}.content ul,.content ol{margin:0 0 14px;padding-left:24px}.content li{margin:4px 0}'
  + 'blockquote{border-left:4px solid #d1d5db;margin:0 0 14px;padding:4px 16px;color:#4b5563}'
  + '.foot{padding:16px 28px;border-top:1px solid #e5e7eb;font-size:13px;color:#4b5563}.foot code{background:#f3f4f6;padding:1px 6px;border-radius:4px}'
  + 'a.again{display:inline-block;margin-top:10px;color:#2563eb}';

let html;
if (r.status === 'rejected' || r.status === 'failed') {
  const reasons = r.errors && r.errors.length ? r.errors : [r.error || r.message || 'Unknown error'];
  html = '<div class="wrap"><div class="meta"><span class="badge bad">' + esc(r.status) + '</span><span>run ' + esc(r.run_id) + '</span></div>'
    + '<div class="content"><h1>We could not generate this piece</h1><ul>' + reasons.map(x => '<li>' + esc(x) + '</li>').join('') + '</ul>'
    + '<a class="again" href="/form/content-form">Try another topic</a></div></div>';
} else {
  let image = '';
  if (item.binary && item.binary.image) {
    const buffer = await this.helpers.getBinaryDataBuffer(0, 'image');
    image = '<img alt="' + esc(r.title) + '" src="data:' + item.binary.image.mimeType + ';base64,' + buffer.toString('base64') + '">';
  }
  const body = String(r.article_markdown || '').replace(/^#\s+[^\n]*\n+/, '');
  const badge = r.status === 'success' ? 'ok' : 'warn';
  const d = r.diversity || {};
  const t = r.timings_ms || {};
  const revisions = r.quality && r.quality.revisions ? r.quality.revisions : 0;
  html = '<div class="wrap"><div class="meta">'
    + '<span class="badge ' + badge + '">' + esc(r.status.replace('_', ' ')) + '</span>'
    + '<span>' + esc(r.style.replace('_', ' ')) + '</span><span>' + esc(r.word_count) + ' words</span>'
    + (revisions ? '<span>' + revisions + ' revision' + (revisions > 1 ? 's' : '') + '</span>' : '')
    + '<span>' + Math.round((t.total || 0) / 1000) + ' s</span><span>$' + esc(r.cost_usd) + '</span>'
    + '<span>' + esc((r.models || {}).text) + ' + ' + esc((r.models || {}).image || 'no image') + '</span></div>'
    + '<div class="content"><h1>' + esc(r.title) + '</h1><p class="lede">' + esc(r.meta_description) + '</p>' + image + toHtml(body) + '</div>'
    + '<div class="foot">Angle <code>' + esc(d.angle) + '</code> · hook <code>' + esc(d.hook) + '</code> · audience <code>' + esc(d.audience) + '</code><br>'
    + 'Visual: ' + esc((d.visual || {}).style) + ', ' + esc((d.visual || {}).palette) + '<br>'
    + (r.warnings && r.warnings.length ? 'Warnings: ' + r.warnings.map(esc).join('; ') + '<br>' : '')
    + 'Saved to <code>' + esc((r.files || {}).article) + '</code> · run <code>' + esc(r.run_id) + '</code><br>'
    + '<a class="again" href="/form/content-form">Generate another</a></div></div>';
}
return [{ json: { html: '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>' + esc(r.title || 'Content generator') + '</title><style>' + css + '</style></head><body>' + html + '</body></html>' } }];
